    # Check if sub_list is empty, which is trivially a sublist
    if not sub_list:
        return True
    # Check if sub_list is longer than main_list, cannot be a sublist
    if len(sub_list) > len(main_list):
        return False
    # Iterate through main_list to find the sub_list
    for i in range(len(main_list) - len(sub_list) + 1):
        # Check if the slice of main_list matches sub_list
        if main_list[i:i + len(sub_list)] == sub_list:
            return True
    return False

