    # Convert the number to a string to iterate over digits
    str_n = str(n)
    # Initialize the alternating sum
    alt_sum = 0
    # Iterate over the digits and calculate the alternating sum
    for i, digit in enumerate(str_n):
        if i % 2 == 0:
            alt_sum += int(digit)
        else:
            alt_sum -= int(digit)
    # Check if the alternating sum is divisible by 11
    return alt_sum % 11 == 0

