def amicable_numbers_sum(limit):
    def sum_of_divisors(n):
        total = 1
        for i in range(2, int(n**0.5) + 1):
            if n % i == 0:
                total += i
                if i != n // i:
                    total += n // i
        return total

    amicable_sum = 0
    visited = set()

    for num in range(2, limit + 1):
        if num in visited:
            continue
        partner = sum_of_divisors(num)
        if partner != num and sum_of_divisors(partner) == num:
            if num <= limit:
                amicable_sum += num
            if partner <= limit:
                amicable_sum += partner
            visited.add(partner)

    return amicable_sum

