def pancake_sort(arr):
    def flip(sub_arr, k):
        """Helper function to reverse the order of the first k elements of the array."""
        sub_arr[:k] = sub_arr[:k][::-1]

    n = len(arr)
    for size in range(n, 1, -1):
        # Find the index of the maximum element in arr[0:size]
        max_index = max(range(size), key=arr.__getitem__)

        # Move the maximum element to the front if it's not already there
        if max_index != size - 1:
            # Flip the maximum element to the front
            if max_index != 0:
                flip(arr, max_index + 1)
            # Flip it to its correct position
            flip(arr, size)

    return arr

