def is_majority(arr, n, element):
    # Find the first occurrence of the element
    first_occurrence = -1
    low, high = 0, n - 1

    while low <= high:
        mid = (low + high) // 2
        if arr[mid] == element:
            if mid == 0 or arr[mid - 1] != element:
                first_occurrence = mid
                break
            high = mid - 1
        elif arr[mid] < element:
            low = mid + 1
        else:
            high = mid - 1

    # If the element is not found, return False
    if first_occurrence == -1:
        return False

    # Check if the element is the majority element
    last_occurrence = first_occurrence + n // 2
    if last_occurrence < n and arr[last_occurrence] == element:
        return True

    return False

