def lps(s):
    def longest_palindromic_subseq(s, i, j, memo):
        if i > j:
            return 0
        if i == j:
            return 1
        if (i, j) in memo:
            return memo[(i, j)]

        if s[i] == s[j]:
            memo[(i, j)] = 2 + longest_palindromic_subseq(s, i + 1, j - 1, memo)
        else:
            memo[(i, j)] = max(longest_palindromic_subseq(s, i + 1, j, memo),
                               longest_palindromic_subseq(s, i, j - 1, memo))

        return memo[(i, j)]

    # Convert the string to uppercase to make the function case-insensitive
    s = s.upper()
    return longest_palindromic_subseq(s, 0, len(s) - 1, {})

