def max_sum(arr):
    n = len(arr)
    if n == 0:
        return 0

    # Initialize MSIS array where MSIS[i] stores the maximum sum of increasing subsequence ending with arr[i]
    msis = [0] * n
    for i in range(n):
        msis[i] = arr[i]

    # Compute MSIS values in a bottom-up manner
    for i in range(1, n):
        for j in range(i):
            if arr[i] > arr[j] and msis[i] < msis[j] + arr[i]:
                msis[i] = msis[j] + arr[i]

    # Initialize MSDS array where MSDS[i] stores the maximum sum of decreasing subsequence starting with arr[i]
    msds = [0] * n
    for i in range(n):
        msds[i] = arr[i]

    # Compute MSDS values in a bottom-up manner
    for i in reversed(range(n-1)):
        for j in reversed(range(i, n)):
            if arr[i] > arr[j] and msds[i] < msds[j] + arr[i]:
                msds[i] = msds[j] + arr[i]

    # Find the maximum value of msis[i] + msds[i] - arr[i]
    max_sum_bitonic = 0
    for i in range(n):
