def max_sub_array_sum_repeated(arr, n, k):
    def kadane(arr):
        max_ending_here = max_so_far = arr[0]
        for x in arr[1:]:
            max_ending_here = max(x, max_ending_here + x)
            max_so_far = max(max_so_far, max_ending_here)
        return max_so_far

    # Case 1: Get the maximum sum using Kadane's algorithm
    max_kadane = kadane(arr)

    # Case 2: Get the maximum prefix sum
    max_prefix_sum = float('-inf')
    prefix_sum = 0
    for i in range(n):
        prefix_sum += arr[i]
        max_prefix_sum = max(max_prefix_sum, prefix_sum)

    # Case 3: Get the maximum suffix sum
    max_suffix_sum = float('-inf')
    suffix_sum = 0
    for i in range(n - 1, -1, -1):
        suffix_sum += arr[i]
        max_suffix_sum = max(max_suffix_sum, suffix_sum)

    # Case 4: Sum of the array
    total_sum = sum(arr)

    # If k == 1, the result is the maximum subarray sum of the single array
    if k == 1:
        return max_kadane

    # If k > 1, consider the cases where the maximum sum might come from
    # the prefix of the first array and the suffix of the last array
    if total_sum > 0:
        return max(max_kadane, max_prefix_sum + max_suffix_sum + (k - 2) * total_sum)
    else:
        return max(max_kadane, max_prefix_sum + max_suffix_sum)

