def get_total_number_of_sequences(m, n):
    # Create a DP table to store the number of sequences
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    # Base case: There's one way to have a sequence of length 0
    for i in range(m + 1):
        dp[i][0] = 1

    # Fill the DP table
    for length in range(1, n + 1):
        for max_val in range(1, m + 1):
            for prev_val in range(1, max_val // 2 + 1):
                dp[max_val][length] += dp[prev_val][length - 1]

    # Sum up all sequences of length n with max value from 1 to m
    return sum(dp[i][n] for i in range(1, m + 1))

