def max_sum_increasing_subseq(arr, n, i, k):
    # Initialize the msis array where msis[i] stores the maximum sum of increasing subsequence ending with arr[i]
    msis = [0] * n

    # The maximum sum up to each element is at least the element itself
    for j in range(n):
        msis[j] = arr[j]

    # Compute the maximum sum of increasing subsequence for each element up to i
    for j in range(1, i + 1):
        for l in range(j):
            if arr[l] < arr[j] and msis[j] < msis[l] + arr[j]:
                msis[j] = msis[l] + arr[j]

    # Now, we need to ensure that the subsequence includes the element at index k
    # We will consider the maximum sum of increasing subsequence ending at index i and then add arr[k] if arr[i] < arr[k]
    max_sum = 0
    for j in range(i + 1):
        if arr[j] < arr[k]:
            max_sum = max(max_sum, msis[j])

    # The result is the maximum sum found plus the element at index k
    return max_sum + arr[k]

