def set_left_most_unset_bit(n):
    if n == 0:
        return 1

    # Find the highest bit position in n
    highest_bit = 1
    while highest_bit <= n:
        highest_bit <<= 1

    # Start checking from the highest bit downwards
    mask = highest_bit >> 1
