def count_Pairs(arr, n):
    # Create a dictionary to count occurrences of each element
    element_count = {}
    for num in arr:
        if num in element_count:
            element_count[num] += 1
        else:
            element_count[num] = 1

    # Calculate the number of unequal unordered pairs
    pair_count = 0
    for count in element_count.values():
        # If there are k elements of the same value, we can form k * (n - k) pairs with other elements
        pair_count += count * (n - count)

    # Since each pair is counted twice, we divide by 2
    return pair_count // 2

