def count_Pairs(arr, n):
    # Create a dictionary to count occurrences of each number
    count_dict = {}
    for num in arr:
        if num in count_dict:
            count_dict[num] += 1
        else:
            count_dict[num] = 1

    # Calculate the number of unique pairs
    unique_count = 0
    for count in count_dict.values():
        if count > 1:
            # If there are more than one of the same number, we can form pairs within them
            unique_count += (count * (count - 1)) // 2

    # Total pairs possible with n elements
    total_pairs = (n * (n - 1)) // 2

    # Subtract the pairs where both elements are equal
    return total_pairs - unique_count

# Test cases
assert count_Pairs([1,2,1],3) == 2
assert count_Pairs([1,1,1,1],4) == 0
assert count_Pairs([1,2,3,4,5],5) == 10

