def is_Sub_Array(arr, subarr):
    n = len(arr)
    m = len(subarr)

    # A subarray cannot be longer than the array itself
    if m > n:
        return False

    # Check for subarray in arr
    for i in range(n - m + 1):
        j = 0
        while j < m:
            if arr[i + j] != subarr[j]:
                break
            j += 1
        if j == m:
            return True
    return False

