        return -1
    elif n == 1:
        return (arr1[0] + arr2[0]) / 2
    elif n == 2:
        return (max(arr1[0], arr2[0]) + min(arr1[1], arr2[1])) / 2

    # Get the middle index
    mid1 = n // 2
    mid2 = n // 2

    # Compare middle elements of both arrays and discard half of each array
    if arr1[mid1] <= arr2[mid2]:
        return get_median(arr1[mid1:], arr2[:mid2 + 1], n - mid1)
    else:
        return get_median(arr1[:mid1 + 1], arr2[mid2:], n - mid2)

