def last(arr, x):
    # Initialize the result to -1 to handle the case where the element is not found
    result = -1
    # Set the left and right pointers for binary search
    left, right = 0, len(arr) - 1

    # Perform binary search
    while left <= right:
        mid = (left + right) // 2
        if arr[mid] == x:
            result = mid  # Update result to the current mid
            left = mid + 1  # Move right to find the last occurrence
        elif arr[mid] < x:
            left = mid + 1
        else:
            right = mid - 1

    return result

