def get_ludic(n):
    if n < 1:
        return []
    ludics = list(range(1, n + 1))
    index = 1
    while index < len(ludics):
        first_ludic = ludics[index]
        ludics = ludics[:index + 1] + [ludics[i] for i in range(index + 1, len(ludics)) if ludics[i] % first_ludic != 0]
        index += 1
    return ludics

