    set1 = set(list1)
    set2 = set(list2)

    # Find the symmetric difference between the two sets
    difference = set1.symmetric_difference(set2)

    # Convert the set back to a list and maintain the order of the first occurrence
    result = []
    for item in list1:
        if item in difference:
            result.append(item)

    for item in list2:
        if item in difference and item not in result:
            result.append(item)

    # Ensure the order is maintained as per the first list then the second list
    result = []
    for item in list1:
        if item not in set2:
            result.append(item)

    for item in list2:
        if item not in set1:
